solution:
def audit_cookie(header):
    attrs = [part.strip().lower() for part in header.split(";")[1:]]
    problems = []
    if "secure" not in attrs:
        problems.append("нет Secure")
    if "httponly" not in attrs:
        problems.append("нет HttpOnly")
    same_site = [a for a in attrs if a.startswith("samesite=")]
    if not same_site:
        problems.append("нет SameSite")
    elif same_site[0] == "samesite=none" and "secure" not in attrs:
        problems.append("SameSite=None без Secure")
    return problems

